-- FRESHGO TEST FULL BOOTSTRAP (GENERATED) = baseline + migrations in apply order
-- Note: the three same-timestamp 20260822000000 v2.2 files run v2.2 -> v2.2.1 -> v2.2.2
-- Import the whole file in the TEST project SQL Editor and Run. Do not edit by hand.

-- ########## BASELINE: supabase/baseline/00_baseline.sql ##########
-- ════════════════════════════════════════════════════════════════════════════
-- FRESHGO TEST BASELINE — PRE-RELEASE SCHEMA (bootstrap only)
--
-- The repository's migration history (supabase/migrations/) assumes two
-- tables already exist because they were created before the migration era:
--   * "Orders"        — the app's core table; migration 20260712051341 only
--                       ALTERs it and its header explicitly says RLS was
--                       "already enabled".
--   * site_settings   — never created in migrations; only INSERTed/read.
-- Without this baseline, replaying the migrations on a clean database fails at
-- the very first migration.
--
-- This file is NOT an application migration. It lives OUTSIDE supabase/migrations/
-- and exists only to let a fresh TEST project be bootstrapped.
--
-- Apply BEFORE supabase/migrations/*.sql on a fresh database.
-- Never run against production.
-- ════════════════════════════════════════════════════════════════════════════

-- ── Core order table ────────────────────────────────────────────────────────
CREATE TABLE "Orders" (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz
);
ALTER TABLE "Orders" ENABLE ROW LEVEL SECURITY;

-- ── Site/key-value settings table ───────────────────────────────────────────
CREATE TABLE public.site_settings (
  key        text PRIMARY KEY,
  value      jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- ################################################################
-- 01 migration: 20260712051341_add_order_columns_and_rls.sql
-- ################################################################
/*
# Add customer & order detail columns to Orders table

## Summary
Adds all customer delivery information, item details, and financial summary
columns needed to store a complete order record from the Rimbun FreshGo app.

## Changes to existing table: Orders
### New columns added
- `full_name`       — Customer's full name (text, not null)
- `phone_number`    — Customer's phone number (text, not null)
- `email_address`   — Customer's email address (text, not null)
- `street_address`  — Delivery street address (text, not null)
- `postcode`        — 5-digit Malaysian postcode (text, not null)
- `city`            — Delivery city (text, not null)
- `state`           — Delivery state (text, not null, default 'Selangor')
- `order_notes`     — Optional customer notes / special requests (text, nullable)
- `item_options`    — Per-item preparation preferences as JSON array (jsonb, default '[]')
- `order_items`     — Full array of cart items (name, price, qty, image, etc.) as JSON (jsonb, default '[]')
- `delivery_slot`   — Selected delivery day: 'wednesday' or 'friday' (text, not null)
- `order_summary`   — Human-readable order summary / status timeline as JSON (jsonb, default '{}')
- `subtotal`        — Order subtotal before delivery fee, in RM (numeric(10,2), default 0)
- `delivery_fee`    — Delivery fee charged, in RM (numeric(10,2), default 0)
- `total`           — Grand total (subtotal + delivery_fee), in RM (numeric(10,2), default 0)

## Security
- RLS is already enabled on Orders.
- No policies existed; this migration adds 4 CRUD policies scoped to
  `anon, authenticated` because this app has no sign-in screen and the
  frontend uses only the anon key.

## Notes
1. All ADD COLUMN statements use IF NOT EXISTS so this migration is safe to re-run.
2. Columns that must always be present use NOT NULL with sensible defaults.
3. JSONB columns default to empty array/object so callers can append without
   checking for null.
4. Financial columns use numeric(10,2) to avoid floating-point rounding errors.
*/

-- ── New columns ──────────────────────────────────────────────────────────────

ALTER TABLE "Orders"
  ADD COLUMN IF NOT EXISTS full_name       text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS phone_number    text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS email_address   text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS street_address  text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS postcode        text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS city            text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS state           text NOT NULL DEFAULT 'Selangor',
  ADD COLUMN IF NOT EXISTS order_notes     text,
  ADD COLUMN IF NOT EXISTS item_options    jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS order_items     jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS delivery_slot   text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS order_summary   jsonb NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS subtotal        numeric(10,2) NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS delivery_fee    numeric(10,2) NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS total           numeric(10,2) NOT NULL DEFAULT 0;

-- ── RLS policies (no-auth app — anon + authenticated) ────────────────────────

DROP POLICY IF EXISTS "anon_select_orders" ON "Orders";
CREATE POLICY "anon_select_orders" ON "Orders" FOR SELECT
  TO anon, authenticated USING (true);

DROP POLICY IF EXISTS "anon_insert_orders" ON "Orders";
CREATE POLICY "anon_insert_orders" ON "Orders" FOR INSERT
  TO anon, authenticated WITH CHECK (true);

DROP POLICY IF EXISTS "anon_update_orders" ON "Orders";
CREATE POLICY "anon_update_orders" ON "Orders" FOR UPDATE
  TO anon, authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "anon_delete_orders" ON "Orders";
CREATE POLICY "anon_delete_orders" ON "Orders" FOR DELETE
  TO anon, authenticated USING (true);

-- ################################################################
-- 02 migration: 20260712060952_recreate_product_table.sql
-- ################################################################
/*
# Recreate Product table with requested columns

## Summary
The previous "Product" table (created in an earlier migration) had a different
column set and contained zero rows. This migration drops that empty table and
recreates it with the exact columns requested by the user. No data is lost
because the table was confirmed empty (0 rows) before dropping.

## New Table: Product
Columns:
- `product_id`           — UUID primary key (auto-generated)
- `product_name`          — Product name (text, not null)
- `product_category`      — Product category (text, not null)
- `product_price`         — Unit price in RM (numeric(10,2), not null)
- `product_unit`          — Unit of sale, e.g. "per kg" (text, not null)
- `product_quantity`      — Stock quantity on hand (integer, not null, default 0)
- `product_preparation`   — Preparation / processing options (text, nullable)
- `product_description`   — Product description (text, not null)
- `vendor_name`           — Name of the vendor supplying this product (text, not null)
- `freshness`             — Stock state: available, limited, sold-out (text, not null, default 'available')
- `image`                 — Product image URL (text, not null)
- `created_at`            — Row creation timestamp (timestamptz, default now())

## Security
- RLS enabled on `Product`.
- 4 CRUD policies scoped to `anon, authenticated` because this is a no-auth
  app and the catalog is intentionally public/shared data.

## Notes
1. The table was confirmed empty (0 rows) before dropping, so no data is lost.
2. `product_price` uses `numeric(10,2)` to avoid floating-point rounding on money.
3. `product_quantity` defaults to 0 so new rows start with zero stock.
4. `freshness` is CHECK-constrained to the three valid values the frontend uses.
5. Index added on `product_category` for fast shop-page filtering.
*/

DROP TABLE IF EXISTS "Product";

CREATE TABLE "Product" (
  product_id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_name           text NOT NULL,
  product_category       text NOT NULL,
  product_price          numeric(10,2) NOT NULL,
  product_unit           text NOT NULL,
  product_quantity       integer NOT NULL DEFAULT 0,
  product_preparation    text,
  product_description    text NOT NULL,
  vendor_name            text NOT NULL,
  freshness              text NOT NULL DEFAULT 'available' CHECK (freshness IN ('available', 'limited', 'sold-out')),
  image                  text NOT NULL,
  created_at             timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_product_category ON "Product" (product_category);

ALTER TABLE "Product" ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "anon_select_products" ON "Product";
CREATE POLICY "anon_select_products" ON "Product" FOR SELECT
  TO anon, authenticated USING (true);

DROP POLICY IF EXISTS "anon_insert_products" ON "Product";
CREATE POLICY "anon_insert_products" ON "Product" FOR INSERT
  TO anon, authenticated WITH CHECK (true);

DROP POLICY IF EXISTS "anon_update_products" ON "Product";
CREATE POLICY "anon_update_products" ON "Product" FOR UPDATE
  TO anon, authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "anon_delete_products" ON "Product";
CREATE POLICY "anon_delete_products" ON "Product" FOR DELETE
  TO anon, authenticated USING (true);

-- ################################################################
-- 03 migration: 20260712063102_recreate_product_table_full_schema.sql
-- ################################################################
/*
# Recreate Product table with full schema + seed catalog

## Summary
Drops the existing empty "Product" table and recreates it with a complete
schema that covers both the user-requested columns and all fields from the
Product TypeScript interface. Then seeds all 28 products from the hardcoded
catalog so the app can read from Supabase instead of a TypeScript file.

## Table: Product
Columns:
- `id`                   — Text primary key (e.g. 'broiler-chicken'), matches app
- `name`                 — Product name in English (text, not null)
- `name_ms`              — Product name in Malay (text, not null)
- `category`             — chicken | fish | prawns | squid | combo (text, not null)
- `price`                — Unit price in RM (numeric(10,2), not null)
- `unit`                 — Unit of sale, e.g. "per kg" (text, not null)
- `price_note`            — Optional pricing caveat (text, nullable)
- `weight`               — Optional weight description (text, nullable)
- `quantity`              — Stock quantity on hand (integer, not null, default 0)
- `description`          — Short card description (text, not null)
- `long_description`     — Full detail page description (text, not null)
- `image`                — Primary image URL (text, not null)
- `images`               — Gallery URLs (text[], default '{}')
- `freshness`            — available | limited | sold-out (text, not null, default 'available')
- `preparation_options`  — Allowed prep options (text[], default '{}')
- `vendor_id`            — Vendor ID, e.g. 'vendor-hassan' (text, not null)
- `vendor_name`          — Human-readable vendor name (text, not null)
- `tags`                 — Search/filter tags (text[], default '{}')
- `is_popular`           — Show in "Popular" section (boolean, default false)
- `created_at`           — Row creation timestamp (timestamptz, default now())

## Security
- RLS enabled on `Product`.
- 4 CRUD policies scoped to `anon, authenticated` (no-auth app, public catalog).

## Notes
1. Table was confirmed empty (0 rows) before dropping — no data loss.
2. `id` is TEXT (not uuid) because the app uses string slugs like 'siakap'.
3. All 28 products from src/data/products.ts are seeded via INSERT.
4. Idempotent: DROP + CREATE + INSERT ON CONFLICT DO NOTHING.
*/

DROP TABLE IF EXISTS "Product";

CREATE TABLE "Product" (
  id                    text PRIMARY KEY,
  name                  text NOT NULL,
  name_ms               text NOT NULL,
  category              text NOT NULL CHECK (category IN ('chicken', 'fish', 'prawns', 'squid', 'combo')),
  price                 numeric(10,2) NOT NULL,
  unit                  text NOT NULL,
  price_note            text,
  weight                text,
  quantity              integer NOT NULL DEFAULT 0,
  description           text NOT NULL,
  long_description      text NOT NULL,
  image                 text NOT NULL,
  images                text[] NOT NULL DEFAULT '{}',
  freshness             text NOT NULL DEFAULT 'available' CHECK (freshness IN ('available', 'limited', 'sold-out')),
  preparation_options   text[] NOT NULL DEFAULT '{}',
  vendor_id             text NOT NULL,
  vendor_name           text NOT NULL,
  tags                  text[] NOT NULL DEFAULT '{}',
  is_popular            boolean NOT NULL DEFAULT false,
  created_at            timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_product_category ON "Product" (category);
CREATE INDEX IF NOT EXISTS idx_product_vendor_id ON "Product" (vendor_id);

ALTER TABLE "Product" ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "anon_select_products" ON "Product";
CREATE POLICY "anon_select_products" ON "Product" FOR SELECT
  TO anon, authenticated USING (true);

DROP POLICY IF EXISTS "anon_insert_products" ON "Product";
CREATE POLICY "anon_insert_products" ON "Product" FOR INSERT
  TO anon, authenticated WITH CHECK (true);

DROP POLICY IF EXISTS "anon_update_products" ON "Product";
CREATE POLICY "anon_update_products" ON "Product" FOR UPDATE
  TO anon, authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "anon_delete_products" ON "Product";
CREATE POLICY "anon_delete_products" ON "Product" FOR DELETE
  TO anon, authenticated USING (true);

