  TO authenticated
  USING (public.is_admin());

-- ################################################################
-- 08 migration: 20260718041051_20260718_supplier_weight_entry.sql
-- ################################################################
/*
# Supplier Weight Entry Support

## Summary
Adds the columns and RLS policies required for the Supplier Weight Entry workflow.
Suppliers can read all orders (to see their queue) and update orders (to save
actual weights and change status to awaiting-payment).

## Changes to existing table: Orders
### New columns
- `supplier_weights` (jsonb, default '{}') — map of item-array-index → actual weight in grams
- `updated_at`       (timestamptz, nullable)  — timestamp of the last supplier update
- `updated_by`       (uuid, nullable, FK auth.users) — which supplier saved the weights

## New RLS Policies on Orders
- `supplier_select_orders` — suppliers can SELECT all order rows
- `supplier_update_orders` — suppliers can UPDATE any order row

## Notes
1. is_supplier() already exists from the 20260717_add_supplier_role migration.
2. Columns are nullable / have defaults so existing rows are unaffected.
3. The supplier SELECT policy intentionally covers all orders (not just "confirmed")
   to allow for future status-based workflows without another migration.
4. Supplier UPDATE is intentionally broad for the same reason; business logic
   (e.g. only updating confirmed orders) is enforced in the application layer.
*/

-- 1. New columns on Orders
ALTER TABLE "Orders"
  ADD COLUMN IF NOT EXISTS supplier_weights jsonb        NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS updated_at       timestamptz,
  ADD COLUMN IF NOT EXISTS updated_by       uuid         REFERENCES auth.users(id) ON DELETE SET NULL;

-- 2. Supplier SELECT policy
DROP POLICY IF EXISTS "supplier_select_orders" ON "Orders";
CREATE POLICY "supplier_select_orders" ON "Orders" FOR SELECT
  TO authenticated
  USING (public.is_supplier());

-- 3. Supplier UPDATE policy
DROP POLICY IF EXISTS "supplier_update_orders" ON "Orders";
CREATE POLICY "supplier_update_orders" ON "Orders" FOR UPDATE
  TO authenticated
  USING (public.is_supplier())
  WITH CHECK (public.is_supplier());

-- ################################################################
-- 09 migration: 20260718050215_20260718_create_customer_profiles.sql
-- ################################################################
/*
# Create customer_profiles table

## Summary
Adds a delivery profile store for authenticated customers. When a customer
completes checkout, their name, phone, and address details are saved here.
On future checkouts, these values are pre-populated in the form so the
customer does not have to re-enter them.

## New Table: customer_profiles
Keyed on the auth user's UUID (one row per customer account).

### Columns
- `id`          — uuid, primary key, FK → auth.users(id), CASCADE on delete.
                  Matches auth.uid() so no separate user_id column is needed.
- `full_name`   — customer's full name (text, default '')
- `phone`       — Malaysian phone number (text, default '')
- `address`     — full street / unit / apartment address line (text, default '')
- `postcode`    — 5-digit postcode (text, default '')
- `city`        — city name (text, default '')
- `state`       — Malaysian state (text, default 'Selangor')
- `updated_at`  — timestamp of the last update (timestamptz, default now())

## Security
- RLS enabled.
- Authenticated users can SELECT, INSERT, UPDATE their own row only
  (using auth.uid() = id).
- No DELETE policy — profiles should persist unless the account is deleted
  (handled by CASCADE on the FK).

## Notes
1. Email is intentionally excluded — it already lives in auth.users and must
   not be duplicated here.
2. Defaults are empty strings so an upsert with partial data is safe.
3. This table is separate from supplier_profiles, which stores vendor linkage
   for suppliers. customer_profiles stores delivery preferences only.
4. INSERT is needed in addition to UPDATE because the first time a customer
   places an order there is no existing row to update.
*/

CREATE TABLE IF NOT EXISTS public.customer_profiles (
  id          uuid        PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  full_name   text        NOT NULL DEFAULT '',
  phone       text        NOT NULL DEFAULT '',
  address     text        NOT NULL DEFAULT '',
  postcode    text        NOT NULL DEFAULT '',
  city        text        NOT NULL DEFAULT '',
  state       text        NOT NULL DEFAULT 'Selangor',
  updated_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.customer_profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "select_own_profile" ON public.customer_profiles;
CREATE POLICY "select_own_profile" ON public.customer_profiles FOR SELECT
  TO authenticated USING (auth.uid() = id);

DROP POLICY IF EXISTS "insert_own_profile" ON public.customer_profiles;
CREATE POLICY "insert_own_profile" ON public.customer_profiles FOR INSERT
  TO authenticated WITH CHECK (auth.uid() = id);

DROP POLICY IF EXISTS "update_own_profile" ON public.customer_profiles;
CREATE POLICY "update_own_profile" ON public.customer_profiles FOR UPDATE
  TO authenticated
  USING (auth.uid() = id)
  WITH CHECK (auth.uid() = id);

