-- ################################################################
-- 28 migration: 20260811000000_add_delivery_batches.sql
-- ################################################################
/*
# Delivery Batches (Foundation)

## Summary
Adds the Delivery Batch concept to FreshGo. A batch represents ONE Lalamove
trip that carries MANY packed customer orders from the supplier (Pasar Tani
Putrajaya) to the FreshGo Hub (Residensi Rimbun), where a FreshGo Rider then
delivers each order to the customer.

This migration ONLY creates the database structure. Order assignment,
the Rider dashboard, and customer tracking are intentionally NOT part of
this phase.

## New table: delivery_batches
- `id`                  uuid PK (gen_random_uuid)
- `batch_code`          text UNIQUE (e.g. BATCH-20260803-001, generated by the app)
- `delivery_date`       date — the delivery day the batch serves
- `supplier_name`       text — supplier packing at Pasar Tani Putrajaya
- `supplier_notes`      text — packing / pickup notes for the supplier
- `hub_name`            text default 'Residensi Rimbun' — FreshGo Hub destination
- `lalamove_tracking_url` text — optional Lalamove trip tracking link
- `status`              text default 'pending' (CHECK constrained):
                         pending | packing | awaiting_lalamove | in_transit_to_hub
                         | arrived_at_hub | completed | cancelled
- `created_by`          uuid FK auth.users
- `created_at` / `updated_at` timestamptz

## Orders change
- Adds ONE nullable column `delivery_batch_id uuid REFERENCES delivery_batches(id)
  ON DELETE SET NULL`. No other Orders columns are touched.

## RLS
- Authenticated users may read all batches.
- Only admins may insert / update / delete.

Idempotent: all CREATE/ALTER/POLICY are guarded.
*/

-- 1. delivery_batches table
CREATE TABLE IF NOT EXISTS public.delivery_batches (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  batch_code           text NOT NULL UNIQUE,
  delivery_date        date NOT NULL,
  supplier_name        text,
  supplier_notes       text,
  hub_name             text NOT NULL DEFAULT 'Residensi Rimbun',
  lalamove_tracking_url text,
  status               text NOT NULL DEFAULT 'pending',
  created_by           uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);

-- Status whitelist
ALTER TABLE public.delivery_batches
  DROP CONSTRAINT IF EXISTS delivery_batches_status_check;
ALTER TABLE public.delivery_batches
  ADD CONSTRAINT delivery_batches_status_check
  CHECK (status IN ('pending','packing','awaiting_lalamove','in_transit_to_hub','arrived_at_hub','completed','cancelled'));

-- 2. RLS
ALTER TABLE public.delivery_batches ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "read_delivery_batches" ON public.delivery_batches;
CREATE POLICY "read_delivery_batches" ON public.delivery_batches
  FOR SELECT TO authenticated
  USING (true);

DROP POLICY IF EXISTS "admin_insert_delivery_batches" ON public.delivery_batches;
CREATE POLICY "admin_insert_delivery_batches" ON public.delivery_batches
  FOR INSERT TO authenticated
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "admin_update_delivery_batches" ON public.delivery_batches;
CREATE POLICY "admin_update_delivery_batches" ON public.delivery_batches
  FOR UPDATE TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "admin_delete_delivery_batches" ON public.delivery_batches;
CREATE POLICY "admin_delete_delivery_batches" ON public.delivery_batches
  FOR DELETE TO authenticated
  USING (public.is_admin());

-- 3. Orders snapshot column (ONE nullable column, nothing else touched)
ALTER TABLE "Orders"
  ADD COLUMN IF NOT EXISTS delivery_batch_id uuid REFERENCES public.delivery_batches(id) ON DELETE SET NULL;

-- 4. Indexes for list sorting (delivery_date DESC) and assignment lookups
CREATE INDEX IF NOT EXISTS idx_delivery_batches_date ON public.delivery_batches (delivery_date DESC);
CREATE INDEX IF NOT EXISTS idx_orders_delivery_batch_id ON "Orders" (delivery_batch_id);

-- ################################################################
-- 29 migration: 20260812000000_add_supplier_dispatch_workflow.sql
-- ################################################################
/*
# Supplier Dispatch Workflow (extends Delivery Batches)

## Summary
Adds supplier dispatch tracking to the existing `delivery_batches` module:

    Customer orders -> Supplier packs all orders -> completes packing
      -> books ONE Lalamove (tracking URL + booking ref)
      -> Lalamove delivers to FreshGo Hub
      -> Admin confirms arrival -> Ready For Rider

## Columns (all ADD COLUMN IF NOT EXISTS)
- `packing_started_at`   timestamptz — when the supplier hit "Start Packing"
- `packing_completed_at` timestamptz — when the supplier hit "Packing Completed"
- `lalamove_booked_at`   timestamptz — when the Lalamove booking was saved
- `hub_arrived_at`       timestamptz — when admin confirmed arrival at the hub
- `ready_for_rider_at`   timestamptz — when admin marked the batch ready for the
                                       delivery rider (status unchanged)
- `booking_reference`    text        — optional Lalamove booking reference

## New RPCs (SECURITY DEFINER, so suppliers may act without broad RLS UPDATE)
- `supplier_start_packing`       -> status 'packing',           sets packing_started_at
- `supplier_complete_packing`    -> status 'awaiting_lalamove', sets packing_completed_at
- `supplier_book_lalamove`       -> status 'in_transit_to_hub', sets lalamove_tracking_url,
                                    booking_reference, lalamove_booked_at
- `admin_confirm_hub_arrival`    -> status 'arrived_at_hub',    sets hub_arrived_at
- `admin_mark_ready_for_rider`   -> sets ready_for_rider_at (status unchanged)

State ordering is enforced inside the RPCs. All are idempotent.
*/

-- 1. New columns
ALTER TABLE public.delivery_batches
  ADD COLUMN IF NOT EXISTS packing_started_at   timestamptz,
  ADD COLUMN IF NOT EXISTS packing_completed_at timestamptz,
  ADD COLUMN IF NOT EXISTS lalamove_booked_at   timestamptz,
  ADD COLUMN IF NOT EXISTS hub_arrived_at       timestamptz,
  ADD COLUMN IF NOT EXISTS ready_for_rider_at   timestamptz,
  ADD COLUMN IF NOT EXISTS booking_reference    text;

-- 2. Supplier: start packing
CREATE OR REPLACE FUNCTION public.supplier_start_packing(p_batch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  cur_status text;
  started    timestamptz;
BEGIN
  IF NOT (public.is_supplier() OR public.is_admin()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT status, packing_started_at INTO cur_status, started
  FROM public.delivery_batches WHERE id = p_batch_id;
  IF cur_status IS NULL THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF started IS NOT NULL THEN RETURN; END IF; -- already started
  IF cur_status NOT IN ('pending','packing') THEN
    RAISE EXCEPTION 'Cannot start packing now.';
  END IF;
  UPDATE public.delivery_batches
     SET status = 'packing', packing_started_at = now(), updated_at = now()
   WHERE id = p_batch_id;
END;
$$;

-- 3. Supplier: complete packing
CREATE OR REPLACE FUNCTION public.supplier_complete_packing(p_batch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  cur_status text;
  started    timestamptz;
  completed  timestamptz;
BEGIN
  IF NOT (public.is_supplier() OR public.is_admin()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT status, packing_started_at, packing_completed_at
    INTO cur_status, started, completed
  FROM public.delivery_batches WHERE id = p_batch_id;
  IF cur_status IS NULL THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF completed IS NOT NULL THEN RETURN; END IF;
  IF started IS NULL OR cur_status NOT IN ('packing', 'awaiting_lalamove') THEN
    RAISE EXCEPTION 'Packing must be started first.';
  END IF;
  UPDATE public.delivery_batches
     SET status = 'awaiting_lalamove', packing_completed_at = now(), updated_at = now()
   WHERE id = p_batch_id;
END;
$$;

-- 4. Supplier: book Lalamove (tracking URL must start with https:// )
CREATE OR REPLACE FUNCTION public.supplier_book_lalamove(
  p_batch_id uuid, p_tracking_url text, p_booking_reference text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  cur_status    text;
  packed_at     timestamptz;
BEGIN
  IF NOT (public.is_supplier() OR public.is_admin()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_tracking_url IS NULL OR trim(p_tracking_url) = '' THEN
    RAISE EXCEPTION 'Tracking URL is required.';
  END IF;
  IF p_tracking_url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'Tracking URL must start with https://';
  END IF;

  SELECT status, packing_completed_at INTO cur_status, packed_at
  FROM public.delivery_batches WHERE id = p_batch_id;
  IF cur_status IS NULL THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF packed_at IS NULL THEN
    RAISE EXCEPTION 'Packing must be completed before booking Lalamove.';
  END IF;

  UPDATE public.delivery_batches
     SET lalamove_tracking_url = trim(p_tracking_url),
         booking_reference    = nullif(p_booking_reference, ''),
         lalamove_booked_at   = now(),
         status               = 'in_transit_to_hub',
         updated_at           = now()
   WHERE id = p_batch_id;
END;
$$;

-- 5. Admin: confirm arrival at the hub
CREATE OR REPLACE FUNCTION public.admin_confirm_hub_arrival(p_batch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  tracking text;
  arrived  timestamptz;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;

  SELECT lalamove_tracking_url, hub_arrived_at INTO tracking, arrived
  FROM public.delivery_batches WHERE id = p_batch_id;
  IF tracking IS NULL THEN RAISE EXCEPTION 'Batch not found or no tracking URL.'; END IF;
  IF arrived IS NOT NULL THEN RETURN; END IF;
  IF tracking IS NULL OR trim(tracking) = '' THEN
    RAISE EXCEPTION 'Cannot confirm arrival without a Lalamove tracking URL.';
  END IF;
  UPDATE public.delivery_batches
     SET status = 'arrived_at_hub', hub_arrived_at = now(), updated_at = now()
   WHERE id = p_batch_id;
END;
$$;

-- 6. Admin: mark ready for rider (status unchanged)
CREATE OR REPLACE FUNCTION public.admin_mark_ready_for_rider(p_batch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  cur_status text;
  arrived    timestamptz;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;

  SELECT status, hub_arrived_at INTO cur_status, arrived
  FROM public.delivery_batches WHERE id = p_batch_id;
  IF cur_status IS NULL THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF arrived IS NULL OR cur_status <> 'arrived_at_hub' THEN
    RAISE EXCEPTION 'Batch must have arrived at the hub first.';
  END IF;
  UPDATE public.delivery_batches
     SET ready_for_rider_at = now(), updated_at = now()
   WHERE id = p_batch_id;
END;
$$;

-- ################################################################
-- 30 migration: 20260813000000_add_delivery_manifest.sql
-- ################################################################
/*
# Delivery Manifest (extends Delivery Batches)

## Summary
The Delivery Manifest is the preparation screen shown to the admin (and rider)
before the rider leaves the hub. It summarises every order in a Delivery Batch:
order count, delivery points, product totals, plus per-order Packed/Loaded
checklists.

No new statuses are introduced on `delivery_batches`. The manifest reuses the
existing Dispatch Workflow RPC `admin_mark_ready_for_rider` for the final
"Ready For Rider" action.

## New table
- `delivery_batch_manifest` — per-order Packed / Loaded state for a batch.
  Rows are created lazily (UPSERT) whenever an admin/supplier toggles a flag.
  Nothing else in the app reads this table directly.

## New RPCs (SECURITY DEFINER)
- `manifest_set_packed(batch, order, packed)`  — supplier or admin toggles Packed
- `manifest_set_loaded(batch, order, loaded)`  — admin toggles Loaded

Only the Delivery Batch module is touched: `delivery_batches` is unchanged and
no columns are added to `"Orders"`.
*/

-- 1. Per-order checklist table
CREATE TABLE IF NOT EXISTS public.delivery_batch_manifest (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  batch_id    uuid        NOT NULL REFERENCES public.delivery_batches(id) ON DELETE CASCADE,
  order_id    bigint      NOT NULL REFERENCES "Orders"(id) ON DELETE CASCADE,
  packed      boolean     NOT NULL DEFAULT false,
  loaded      boolean     NOT NULL DEFAULT false,
  packed_at   timestamptz,
  loaded_at   timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (batch_id, order_id)
);

CREATE INDEX IF NOT EXISTS idx_manifest_batch ON public.delivery_batch_manifest (batch_id);

-- RLS: read/write is admin-only (the RPCs below are SECURITY DEFINER and run as
-- the owner, so they bypass this for suppliers too).
ALTER TABLE public.delivery_batch_manifest ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "admin_select_manifest" ON public.delivery_batch_manifest;
CREATE POLICY "admin_select_manifest" ON public.delivery_batch_manifest
  FOR SELECT TO authenticated
  USING (public.is_admin());

DROP POLICY IF EXISTS "admin_write_manifest" ON public.delivery_batch_manifest;
CREATE POLICY "admin_write_manifest" ON public.delivery_batch_manifest
  FOR INSERT TO authenticated
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "admin_update_manifest" ON public.delivery_batch_manifest;
CREATE POLICY "admin_update_manifest" ON public.delivery_batch_manifest
  FOR UPDATE TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

-- 2. Toggle Packed (supplier or admin)
CREATE OR REPLACE FUNCTION public.manifest_set_packed(
  p_batch_id uuid, p_order_id bigint, p_packed boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT (public.is_admin() OR public.is_supplier()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  INSERT INTO public.delivery_batch_manifest (batch_id, order_id, packed, packed_at)
  VALUES (p_batch_id, p_order_id, p_packed, CASE WHEN p_packed THEN now() ELSE NULL END)
  ON CONFLICT (batch_id, order_id)
  DO UPDATE SET
    packed      = EXCLUDED.packed,
    packed_at   = CASE WHEN EXCLUDED.packed THEN now() ELSE NULL END,
    updated_at  = now();
END;
$$;

-- 3. Toggle Loaded (admin only)
CREATE OR REPLACE FUNCTION public.manifest_set_loaded(
  p_batch_id uuid, p_order_id bigint, p_loaded boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  INSERT INTO public.delivery_batch_manifest (batch_id, order_id, loaded, loaded_at)
  VALUES (p_batch_id, p_order_id, p_loaded, CASE WHEN p_loaded THEN now() ELSE NULL END)
  ON CONFLICT (batch_id, order_id)
  DO UPDATE SET
    loaded      = EXCLUDED.loaded,
    loaded_at   = CASE WHEN EXCLUDED.loaded THEN now() ELSE NULL END,
    updated_at  = now();
END;
$$;

-- ################################################################
-- 31 migration: 20260814000000_add_rider_delivery_workflow.sql
-- ################################################################
/*
# Delivery Rider Dashboard Workflow (extends Delivery Batches)

## Summary
Drives the single-rider delivery workflow on top of the existing Delivery Batch
module. The rider opens the day's batch, starts delivery, works through stops
grouped by Delivery Point, marks each order Delivered, and the batch completes
automatically once every order in it is Delivered.

## Changes to `delivery_batches`
- New columns (ADD COLUMN IF NOT EXISTS):
  - `delivery_started_at` timestamptz — when the rider started the round
  - `completed_at`        timestamptz — when every order was Delivered
- Status CHECK now also allows `out_for_delivery`.
  (The other statuses are unchanged; admin CRUD is untouched.)

## New RPCs (SECURITY DEFINER)
- `rider_start_batch_delivery(p_batch_id)` — rider/admin. Only when the batch
  status is `arrived_at_hub` OR `ready_for_rider_at` is set. Sets status
  `out_for_delivery` and records `delivery_started_at` (kept on re-entry).
- `rider_complete_batch_if_done(p_batch_id)` — rider/admin. When every order
  assigned to the batch has `delivery_status = 'delivered'`, sets the batch to
  `completed` and records `completed_at`. No-op otherwise.

The existing per-order RPC `rider_update_delivery_status` moves an individual
order to `delivered`; nothing here modifies that function.

## RLS
No RLS changes: riders already have SELECT on `delivery_batches` (authenticated
read) and SELECT on all `"Orders"` via `rider_select_orders`. The RPCs are
SECURITY DEFINER and run as the owner.
*/

-- 1. New columns
ALTER TABLE public.delivery_batches
  ADD COLUMN IF NOT EXISTS delivery_started_at timestamptz,
  ADD COLUMN IF NOT EXISTS completed_at        timestamptz;

-- 2. Allow 'out_for_delivery' in the status check
ALTER TABLE public.delivery_batches
  DROP CONSTRAINT IF EXISTS delivery_batches_status_check;
ALTER TABLE public.delivery_batches
  ADD CONSTRAINT delivery_batches_status_check
  CHECK (status IN (
    'pending','packing','awaiting_lalamove','in_transit_to_hub',
    'arrived_at_hub','out_for_delivery','completed','cancelled'
  ));

-- 3. Start delivery
CREATE OR REPLACE FUNCTION public.rider_start_batch_delivery(p_batch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  cur_status  text;
  ready_at    timestamptz;
BEGIN
  IF NOT (public.is_delivery_rider() OR public.is_admin()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT status, ready_for_rider_at INTO cur_status, ready_at
  FROM public.delivery_batches WHERE id = p_batch_id;
  IF cur_status IS NULL THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF cur_status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'Batch is already finished';
  END IF;
  IF cur_status <> 'arrived_at_hub' AND ready_at IS NULL THEN
    RAISE EXCEPTION 'Batch is not ready for delivery yet';
  END IF;

  UPDATE public.delivery_batches
     SET status = 'out_for_delivery',
         delivery_started_at = COALESCE(delivery_started_at, now()),
         updated_at = now()
   WHERE id = p_batch_id;
END;
$$;

-- 4. Auto-complete the batch when every order is delivered
CREATE OR REPLACE FUNCTION public.rider_complete_batch_if_done(p_batch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT (public.is_delivery_rider() OR public.is_admin()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE public.delivery_batches b
     SET status = 'completed',
         completed_at = now(),
         updated_at   = now()
   WHERE b.id = p_batch_id
     AND b.status IN ('out_for_delivery', 'arrived_at_hub')
     AND (SELECT count(*) FROM "Orders" o WHERE o.delivery_batch_id = p_batch_id) > 0
     AND NOT EXISTS (
       SELECT 1 FROM "Orders" o
       WHERE o.delivery_batch_id = p_batch_id
         AND (o.delivery_status IS DISTINCT FROM 'delivered')
     );
END;
$$;

-- ################################################################
-- 32 migration: 20260815000000_add_customer_tracking.sql
-- ################################################################
/*
# Customer Live Tracking — helper RPC

## Summary
Connects the existing Customer Order Tracking page to the Delivery Batch and
Delivery Assignment modules WITHOUT duplicating any status columns.

- Order status (`delivery_status`, `delivered_at`) lives on "Orders".
- Delivery progress (`status`, `lalamove_tracking_url`, `hub_name`) lives on
  `delivery_batches` (already readable by authenticated customers).
- The assigned rider for a day lives in `delivery_assignments` (rider/admin only,
  no customer policy).

This migration adds ONE SECURITY DEFINER RPC that resolves the rider's display
name for a delivery date. The customer may only query the date they actually
have an order on (checked against `Orders.user_id`), so no internal rider data
leaks to arbitrary users.

No tables, columns, or status fields are created.
*/

-- Resolve the assigned rider's name for a delivery date.
-- Returns NULL when no rider is assigned or the caller has no order that day.
-- The caller's order date is resolved via delivery_batches (Orders.delivery_date
-- no longer exists; the batch owns the date).
CREATE OR REPLACE FUNCTION public.tracking_rider_name(p_delivery_date date)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  rider_name text;
BEGIN
  IF NOT (
    EXISTS (
      SELECT 1
      FROM "Orders" o
      JOIN public.delivery_batches db ON db.id = o.delivery_batch_id
      WHERE o.user_id = auth.uid()
        AND db.delivery_date = p_delivery_date
    )
    OR public.is_admin()
    OR public.is_delivery_rider()
  ) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(
    NULLIF(au.raw_user_meta_data ->> 'full_name', ''),
    NULLIF(au.raw_user_meta_data ->> 'name', ''),
    au.email
  )
  INTO rider_name
  FROM public.delivery_assignments da
  JOIN auth.users au ON au.id = da.rider_id
  WHERE da.delivery_date = p_delivery_date
  ORDER BY da.id
  LIMIT 1;

  RETURN rider_name;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.tracking_rider_name(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tracking_rider_name(date) TO authenticated;

-- ################################################################
-- 33 migration: 20260816000000_orders_own_supplier_dispatch.sql
-- ################################################################
/*
# Orders Own The Supplier Dispatch Workflow

## Summary
Moves the supplier packing / dispatch workflow from `delivery_batches` onto the
`"Orders"` table. Each order now owns its own operational timestamps, so the
supplier queues never depend on whether a delivery batch has been created.

Delivery batches remain ONLY for logistics grouping and reporting (batch CRUD,
manifests, rider assignment). They no longer control supplier queues, packing,
or customer order progress.

## Orders columns (all ADD COLUMN IF NOT EXISTS)
- `packing_started_at`           timestamptz — supplier hit "Start Packing"
- `packing_completed_at`         timestamptz — supplier hit "Preparation Completed"
- `supplier_dispatch_started_at` timestamptz — Lalamove booked / dispatch started
- `supplier_dispatch_completed_at` timestamptz — arrived at FreshGo hub
- `ready_for_rider_at`           timestamptz — admin marked the order ready for the rider
- `lalamove_tracking_url`        text        — Lalamove tracking link
- `booking_reference`            text        — optional Lalamove booking reference
- `lalamove_booked_at`           timestamptz — when the booking was saved

## New RPCs (SECURITY DEFINER, supplier/admin, idempotent)
- `supplier_start_packing_order(p_order_id)`        -> packing_started_at
- `supplier_complete_packing_order(p_order_id)`     -> packing_completed_at
- `supplier_book_lalamove_order(p_order_id, tracking_url, booking_reference)`
  -> lalamove_tracking_url, booking_reference, lalamove_booked_at,
